// Generate a version string. Sometimes force a canonical numeric.major minor form to exercise parsing paths.
int local_major = 0;
int local_minor = 0;
std::string version = FUZZ_PARAM_STR();
unsigned mode = *FUZZ_PARAM(unsigned int) % 3u;
if (mode == 0u) {
    // Strict "X.Y" with small numeric ranges to avoid overflows and keep fast.
    unsigned int a = *FUZZ_PARAM(unsigned int) % 1000u;
    unsigned int b = *FUZZ_PARAM(unsigned int) % 1000u;
    version = std::to_string(a) + "." + std::to_string(b);
} else if (mode == 1u) {
    // "X.Y-suffix" where suffix is short random data.
    unsigned int a = *FUZZ_PARAM(unsigned int) % 1000u;
    unsigned int b = *FUZZ_PARAM(unsigned int) % 1000u;
    std::string extra = FUZZ_PARAM_STR();
    if (extra.size() > 16u) extra.resize(16u);
    version = std::to_string(a) + "." + std::to_string(b) + "-" + extra;
}
// major/minor pointers must be valid non-null; use local stack variables.
ParseVersion(version, &local_major, &local_minor);
// Validation summary: We ensure non-null writable pointers and provide diverse version formats; no assumptions/assertions are made about parser behavior on malformed strings.
